  "Documento sin guardar" = "Unsaved document", "Sin documento" = "No document",
  "Selecciona Editor y un destino de c\u00f3digo R (script .R o documento sin guardar) antes de activar Auto." = "Choose Editor and an R code target (.R script or unsaved document) before enabling Auto."
)

.tr_ui <- function(text, language = "es") {
  if (!identical(language, "en")) return(text)
  result <- unname(.ui_dictionary()[text])
  if (length(result) == 1L && !is.na(result)) result else text
}
